/* One planning controller: switches never render an intermediate view or refetch. */
(()=>{'use strict';if(!document.body.classList.contains('shared-app'))return;
const DAY=86400000,iso=n=>new Date(n).toISOString().slice(0,10),stamp=s=>Date.parse(s+'T12:00:00Z');
let ganttZoom='day';let mode='calendar',from='',to='',activeProject=null,cached=[],loaded=0,inflight=null;
const todayKey=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const compact=s=>new Intl.DateTimeFormat('fa-IR',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(stamp(s)));
function defaults(){const p=SamandisDates.display(todayKey()).split('/').map(Number);from=SamandisDates.parse(p[0]+'/'+p[1]+'/1');let last=29;for(let i=30;i<=31;i++)if(SamandisDates.parse(p[0]+'/'+p[1]+'/'+i))last=i;to=SamandisDates.parse(p[0]+'/'+p[1]+'/'+last)}
function valid(){return scope==='program'&&project?.id===activeProject&&!window.SAMANDIS_PERSONAL_MODE}
function taskRows(){return [...tasks.filter(t=>t.due).map(t=>({id:t.id,title:t.title,start:(t.starts_on||t.created_at||t.due).slice(0,10),due:t.due,status:labels[t.status],owner:person(t.owner_id),inferred:!t.starts_on,done:t.status==='done',review:t.status==='review'})),...cached.map(m=>({id:m.id,title:m.title,start:m.starts_on||m.due,due:m.due,status:'تحویل پروژه',delivery:true}))]}
function action(r,extra=''){return '<button type="button" class="'+extra+'" data-plan-id="'+esc(r.id)+'" data-plan-delivery="'+!!r.delivery+'">'+esc(r.title)+'</button>'}
function calendar(rows){const lo=stamp(from),hi=stamp(to),offset=(new Date(lo).getUTCDay()+1)%7,days=Math.round((hi-lo)/DAY)+1;let cells=Array(offset).fill('<div class="plan-day blank" aria-hidden="true"></div>').join('');for(let n=lo;n<=hi;n+=DAY){const key=iso(n),parts=SamandisDates.display(key).split('/');cells+='<div class="plan-day '+(key===todayKey()?'today':'')+'"><time datetime="'+key+'" title="'+date(key)+'"><b>'+fa(Number(parts[2]))+'</b><small>'+compact(key).replace(/^[۰-۹0-9]+\s*/,'')+'</small></time>'+rows.filter(r=>r.due===key).map(r=>'<div class="plan-event '+(r.delivery?'delivery':r.done?'done':'')+'">'+action(r)+'</div>').join('')+'</div>'}cells+=Array((7-(offset+days)%7)%7).fill('<div class="plan-day blank" aria-hidden="true"></div>').join('');return '<div class="plan-calendar-scroll"><div class="plan-calendar">'+['شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه'].map(d=>'<div class="plan-weekday">'+d+'</div>').join('')+cells+'</div></div>'}
function gantt(rows){const lo=stamp(from),hi=stamp(to)+DAY,count=Math.round((hi-lo)/DAY),unit=ganttZoom==='day'?38:14,width=count*unit,visible=rows.filter(r=>stamp(r.due)>=lo&&Math.min(stamp(r.start),stamp(r.due))<hi).sort((a,b)=>a.start.localeCompare(b.start)||a.due.localeCompare(b.due)),todayOffset=(stamp(todayKey())-lo)/DAY,todayVisible=todayOffset>=0&&todayOffset<count;let months=[],ticks='';for(let i=0;i<count;i++){const d=iso(lo+i*DAY),month=new Intl.DateTimeFormat('fa-IR',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(stamp(d)));if(months.at(-1)?.name===month)months.at(-1).days++;else months.push({name:month,days:1});const friday=new Date(stamp(d)).getUTCDay()===5;ticks+='<div class="g2-date '+(friday?'weekend ':'')+(d===todayKey()?'current':'')+'" style="width:'+unit+'px" title="'+date(d)+'">'+(ganttZoom==='day'?'<b>'+fa(Number(SamandisDates.display(d).split('/')[2]))+'</b><small>'+new Intl.DateTimeFormat('fa-IR',{weekday:'short',timeZone:'UTC'}).format(new Date(stamp(d)))+'</small>':i%7===0?'<b>'+compact(d)+'</b>':'')+'</div>'}
return '<div class="g2-toolbar"><div class="g2-legend"><span class="open">در دست انجام</span><span class="review">منتظر تأیید</span><span class="done">انجام‌شده</span><span class="delivery">تحویل پروژه</span></div><button type="button" id="ganttGoToday" class="g2-today-button">نمایش امروز</button><label>مقیاس زمان<select id="ganttZoom"><option value="day" '+(ganttZoom==='day'?'selected':'')+'>روزانه</option><option value="week" '+(ganttZoom==='week'?'selected':'')+'>هفتگی</option></select></label></div><div class="g2-scroll" tabindex="0" aria-label="جدول زمانی گانت؛ برای دیدن روزهای دیگر پیمایش کنید"><div class="g2-chart" style="--g2-time-width:'+width+'px;--g2-unit:'+unit+'px"><div class="g2-header"><div class="g2-corner"><b>کار و مسئول انجام</b><small>بازهٔ شروع تا مهلت</small></div><div class="g2-time-header"><div class="g2-months">'+months.map(m=>'<b style="width:'+m.days*unit+'px">'+m.name+'</b>').join('')+'</div><div class="g2-dates">'+ticks+'</div></div></div>'+visible.map(r=>{const start=stamp(r.start),end=stamp(r.due),invalid=start>end,first=Math.max(0,(Math.min(start,end)-lo)/DAY),last=Math.min(count,(end-lo)/DAY+1),barWidth=Math.max(3,(last-first)*unit),short=barWidth<145,klass=r.delivery?'delivery':r.done?'done':r.review?'review':'open',duration=invalid?1:Math.round((end-start)/DAY)+1;return '<div class="g2-row"><div class="g2-label"><div class="g2-task-title"><i class="'+klass+'"></i>'+action(r)+'</div><span class="g2-owner">'+esc(r.owner||'تحویل پروژه')+'</span><small title="'+(r.inferred?'شروع از تاریخ تعریف کار محاسبه شده':'بازه برنامه‌ریزی‌شده')+'">'+compact(r.start)+' ← '+compact(r.due)+' · '+fa(duration)+' روز'+(invalid?' · تاریخ‌ها نیاز به اصلاح دارند':'')+'</small></div><div class="g2-track" style="'+(ganttZoom==='week'?'--g2-unit:'+7*unit+'px':'')+'">'+(todayVisible?'<i class="g2-today" style="right:'+(todayOffset+.5)*unit+'px" title="امروز"></i>':'')+'<button class="g2-bar '+klass+(short?' narrow':'')+'" data-plan-id="'+esc(r.id)+'" data-plan-delivery="'+!!r.delivery+'" style="right:'+first*unit+'px;width:'+barWidth+'px" aria-label="'+esc(r.title)+'؛ '+date(r.start)+' تا '+date(r.due)+'؛ '+esc(r.status)+'" title="'+esc(r.title)+' · '+esc(r.status)+'"><span>'+esc(r.title)+'</span></button>'+(r.delivery?'<button class="g2-milestone" data-plan-id="'+esc(r.id)+'" data-plan-delivery="true" style="right:'+(last*unit-7)+'px" title="تحویل: '+esc(r.title)+'" aria-label="تحویل '+esc(r.title)+'"></button>':'')+'</div></div>'}).join('')+(!visible.length?'<div class="g2-blank"><div></div><div></div></div>':'')+'</div></div>'}
function draw(){if(!valid())return;const root=el('#sharedContent'),scroll=root.querySelector('.g2-scroll'),scrollLeft=scroll?.scrollLeft||0,scrollTop=scroll?.scrollTop||0,focus=root.querySelector('[data-plan-mode]:focus')?.dataset.planMode,rows=taskRows(),undated=tasks.filter(t=>!t.due);root.innerHTML='<div class="plan-workspace"><div class="plan-toolbar"><div><h2>برنامهٔ پروژه</h2><p>'+date(from)+' تا '+date(to)+'</p></div><div class="plan-tabs" role="group" aria-label="نمای برنامه">'+[['calendar','تقویم'],['gantt','گانت']].map(([v,l])=>'<button type="button" data-plan-mode="'+v+'" aria-pressed="'+(mode===v)+'" class="'+(mode===v?'active':'')+'">'+l+'</button>').join('')+'</div></div><form id="programRange" class="range-controls"><label>از تاریخ<input type="date" name="from" value="'+from+'" required></label><label>تا تاریخ<input type="date" name="to" value="'+to+'" required></label><button class="primary">اعمال بازه</button><button type="button" id="planReset" class="secondary">ماه جاری</button><button type="button" id="planRefresh" class="text-btn">تازه‌سازی</button>'+(management()?'<button type="button" id="planDelivery" class="secondary">＋ تحویل پروژه</button>':'')+'</form><section class="plan-surface">'+(mode==='calendar'?calendar(rows):gantt(rows))+'</section><details class="plan-undated" '+(!rows.length?'open':'')+'><summary>'+fa(undated.length)+' کار بدون مهلت · تعیین زمان‌بندی</summary><p>برای نمایش روی گانت و تقویم، کار را باز کنید و از ویرایش، مهلت آن را مشخص کنید.</p>'+undated.map(t=>action(t,'plan-undated-task')).join('')+'</details><p class="shared-meta">تقویم: موعد تحویل · گانت: شروع تا مهلت (در نبود تاریخ شروع، تاریخ تعریف کار)</p></div>';
if(el('#ganttGoToday'))el('#ganttGoToday').onclick=()=>{const today=root.querySelector('.g2-today');if(today)today.scrollIntoView({inline:'center',block:'nearest',behavior:'smooth'});else message('امروز خارج از بازهٔ انتخابی است.')};if(el('#ganttZoom'))el('#ganttZoom').onchange=e=>{ganttZoom=e.target.value;draw()};const updatedScroll=root.querySelector('.g2-scroll');if(updatedScroll){updatedScroll.scrollLeft=scrollLeft;updatedScroll.scrollTop=scrollTop}root.querySelectorAll('[data-plan-mode]').forEach(b=>b.onclick=()=>{const form=el('#programRange'),f=new FormData(form);if(!apply(f,false))return;mode=b.dataset.planMode;draw()});root.querySelectorAll('[data-plan-id]').forEach(b=>b.onclick=()=>b.dataset.planDelivery==='true'?window.SamandisMilestoneForm?.(cached.find(m=>m.id===b.dataset.planId)):detail(b.dataset.planId));el('#programRange').onsubmit=e=>{e.preventDefault();if(apply(new FormData(e.target),true))draw()};el('#planReset').onclick=()=>{defaults();draw()};el('#planRefresh').onclick=()=>{loaded=0;renderProgram()};if(el('#planDelivery'))el('#planDelivery').onclick=()=>window.SamandisMilestoneForm?.();if(focus)root.querySelector('[data-plan-mode="'+mode+'"]').focus()}
function apply(f,report){const a=f.get('from'),b=f.get('to');if(!a||!b||!Number.isFinite(stamp(a))||!Number.isFinite(stamp(b))||a>b){message('بازهٔ تاریخ معتبر نیست؛ شروع باید قبل از پایان باشد.');return false}if((stamp(b)-stamp(a))/DAY>365){message('بازه را حداکثر یک سال انتخاب کنید.');return false}from=a;to=b;return true}
renderProgram=function(force=false){const pid=project?.id;if(!pid)return Promise.resolve();if(force===true)loaded=0;if(activeProject===pid&&valid()){const draft=el("#programRange");if(draft){const f=new FormData(draft);if(f.get("from")!==from||f.get("to")!==to)return Promise.resolve()}}if(activeProject!==pid){activeProject=pid;cached=[];loaded=0;inflight=null;defaults()}draw();if(Date.now()-loaded<20000)return Promise.resolve();if(inflight)return inflight;inflight=checked(db.from('sm_milestones').select('*').eq('project_id',pid).order('due')).then(list=>{if(activeProject!==pid)return;cached=list;loaded=Date.now();if(valid()){const form=el('#programRange');if(form){const f=new FormData(form);if(f.get('from')!==from||f.get('to')!==to)return}draw()}}).catch(e=>{if(valid())message(failure(e))}).finally(()=>{if(activeProject===pid)inflight=null});return inflight};
})();
